mapper.select:
SELECT knowledge_point_id AS kpId, AVG(mastery) AS avgMastery, COUNT(*) AS questionCount FROM question WHERE status = 1 AND knowledge_point_id IS NOT NULL
AND user_id = #{userId}
GROUP BY knowledge_point_id

SELECT DATE(create_time) AS d, COUNT(*) AS cnt
FROM question
WHERE status = 1
  AND create_time >= #{since}

  AND user_id = #{userId}

GROUP BY DATE(create_time)
